CREATE OR ALTER PROCEDURE [dbo].[uspFoodSafetyChecklist_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @EffectiveOn DATE = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[Code]
			, t.[Name]
			, t.[VersionNo]
			, t.[AreaCode]
			, t.[FrequencyCode]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[Status]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[FoodSafetyChecklist] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%') OR t.[AreaCode] LIKE CONCAT('%', @SearchText, '%') OR t.[FrequencyCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@EffectiveOn IS NULL OR ((t.[EffectiveFrom] IS NULL OR t.[EffectiveFrom] <= @EffectiveOn) AND (t.[EffectiveTo] IS NULL OR t.[EffectiveTo] >= @EffectiveOn)))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'versionNo' THEN r.[VersionNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'versionNo' THEN r.[VersionNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'areaCode' THEN r.[AreaCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'areaCode' THEN r.[AreaCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'frequencyCode' THEN r.[FrequencyCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'frequencyCode' THEN r.[FrequencyCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
